ALTER TABLE "trading_paper_workspaces" ADD COLUMN "researchSource" JSONB;
CREATE TABLE "trading_paper_research_snapshots" ("ledgerId" TEXT NOT NULL,"sessionRevision" INTEGER NOT NULL CHECK ("sessionRevision" > 0),"scheduledFor" TIMESTAMP(3) NOT NULL,"envelope" JSONB NOT NULL,"envelopeSha256" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "trading_paper_research_snapshots_pkey" PRIMARY KEY ("ledgerId","sessionRevision","scheduledFor"),CONSTRAINT "trading_paper_research_snapshots_ledgerId_fkey" FOREIGN KEY ("ledgerId") REFERENCES "trading_paper_ledgers"("id") ON DELETE CASCADE ON UPDATE CASCADE);
